mapper.select:
SELECT f.*
FROM flashcard f
INNER JOIN flashcard_deck d ON f.deck_id = d.id
WHERE d.user_id = #{userId}
  AND f.next_review_date <= #{today}
  AND f.status = 1
  AND d.status = 1

      AND f.deck_id IN

          #{deckId}


ORDER BY f.next_review_date ASC, f.id ASC

