    deck_id, question, answer, next_review_date, stage,
    review_count, correct_count, wrong_count, difficulty, status
) VALUES (
    #{deckId}, #{question}, #{answer}, #{nextReviewDate}, #{stage},
    #{reviewCount}, #{correctCount}, #{wrongCount}, #{difficulty}, #{status}
)
